python3 - << 'PY'
import csv
from math import isnan
f='/tmp/exoplanet_eu_catalog.csv'
rows=[]
with open(f, newline='', encoding='utf-8') as csvfile:
    reader=csv.DictReader(csvfile)
    for r in reader:
        rows.append(r)
# Filter
cands=[]
for r in rows:
    det=r.get('detection_type','') or r.get('detection_type')
    if not det: det=''
    if 'Radial Velocity' not in det and 'Radial velocity' not in det and 'Radial Velocity' not in r.get('detection_type',''):
        # some have 'Radial Velocity, Astrometry' etc; check substring
        pass
    # better: case-insensitive contains 'radial'
    if 'radial' not in det.lower():
        continue
    # discovered year
    disc=r.get('discovered','').strip()
    try:
        disc_year=int(disc)
    except:
        # sometimes date? try split
        try:
            disc_year=int(disc.split('-')[0])
        except:
            continue
    if disc_year>=2020:
        continue
    # orbital period
    op=r.get('orbital_period','') or r.get('orbital_period')
    try:
        opf=float(op)
    except:
        try:
            opf=float(r.get('orbital_period','0'))
        except:
            continue
    if opf<100:
        continue
    # mass: try mass_sini then mass
    mass=None
    for key in ['mass_sini','mass_sini','mass_sini_error_min','mass','mass_sini']:
        pass
    # take 'mass_sini' column which appears named 'mass_sini' in header
    ms=r.get('mass_sini','').strip()
    if not ms:
        ms=r.get('mass_sini_error_min','').strip() if r.get('mass_sini_error_min') else ''
    if ms:
        try:
            m_js=float(ms)
            # likely in Jupiter masses; convert to Earth
            m_earth=m_js*317.828
            mass=m_earth
        except:
            mass=None
    # try column 'mass' which may be in Jupiter too
    if mass is None or mass==0:
        m=r.get('mass','').strip()
        if m:
            try:
                m_j=float(m)
                mass=m_j*317.828
            except:
                mass=None
    if mass is None:
        continue
    if mass>5.0000001:
        continue
    # eccentricity
    ecc=r.get('eccentricity','').strip()
    try:
        e=float(ecc) if ecc!='' else 0.0
    except:
        e=0.0
    cands.append((r['name'],mass,opf,e,disc_year,r.get('publication',''),r.get('star_name',''),r.get('alternate_names',''),r.get('detection_type','')))
# Sort by eccentricity descending
cands_sorted=sorted(cands,key=lambda x: x[3],reverse=True)
print('Found',len(cands_sorted),'candidates')
for c in cands_sorted[:30]:
    print(c)
PY
